function getSafeAvatarFallback(name = 'Candidato') {
  const parts = String(name || 'CP').replace(/[^a-zA-ZÀ-ÿ\s]/g, '').trim().split(/\s+/).filter(Boolean);
  const initials = parts.length >= 2 
    ? (parts[0][0] + parts[parts.length - 1][0]).toUpperCase()
    : (parts[0] ? parts[0].slice(0, 2).toUpperCase() : 'CP');
  return `data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 128 128"><defs><linearGradient id="g" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" stop-color="%231e40af"/><stop offset="100%" stop-color="%230284c7"/></linearGradient></defs><rect width="128" height="128" rx="28" fill="url(%23g)"/><text x="50%" y="54%" dominant-baseline="middle" text-anchor="middle" fill="%23ffffff" font-family="-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif" font-size="44" font-weight="700">${initials}</text></svg>`;
}

function getSafeAvatarUrl(candOrUrl, name = 'Candidato') {
  if (typeof candOrUrl === 'object' && candOrUrl !== null) {
    const id = candOrUrl.id || candOrUrl.candidateId;
    if (candOrUrl.officePower === 'judiciario' && id) {
      return `img/judiciary/${id}.jpg`;
    }
    if (id && typeof id === 'string' && (id.startsWith('cand-') || id.startsWith('jud-'))) {
      return id.startsWith('jud-') ? `img/judiciary/${id}.jpg` : `img/candidates/${id}.jpg`;
    }
    if (candOrUrl.avatar) {
      return getSafeAvatarUrl(candOrUrl.avatar, candOrUrl.name || candOrUrl.ballotName || name);
    }
  }

  let url = (typeof candOrUrl === 'string') ? candOrUrl.trim() : '';

  if (!url) {
    return getSafeAvatarFallback(name);
  }

  if (url.startsWith('img/')) {
    return url;
  }

  // Tenta resolver por ID ou Nome no catálogo global
  if (typeof candidatesData !== 'undefined' && Array.isArray(candidatesData)) {
    const found = candidatesData.find(c => c.id === url || c.avatar === url || c.name === name || c.ballotName === name);
    if (found && found.id) {
      if (found.officePower === 'judiciario') return `img/judiciary/${found.id}.jpg`;
      return `img/candidates/${found.id}.jpg`;
    }
  }

  if (url.includes('senado.leg.br') || url.includes('wikimedia.org') || url.includes('wikipedia.org')) {
    return '/api/proxy-image?url=' + encodeURIComponent(url);
  }

  return url;
}

function calculateCivicRelativization(cand) {
  if (!cand || cand.officePower === 'judiciario') return null;
  let rawVal = cand.campaignExpensesTotal || cand.campaignTotal || cand.campaignFinance?.totalSpent || 0;
  if (typeof rawVal === 'string') {
    const lower = rawVal.toLowerCase();
    if (lower.includes('milh') || lower.includes('mi') || lower.includes('m')) {
      const num = parseFloat(rawVal.replace(/[^0-9,\.]/g, '').replace(',', '.'));
      rawVal = (num || 2.4) * 1000000;
    } else if (lower.includes('mil') || lower.includes('k')) {
      const num = parseFloat(rawVal.replace(/[^0-9,\.]/g, '').replace(',', '.'));
      rawVal = (num || 500) * 1000;
    } else {
      const cleaned = rawVal.replace(/[^0-9,\.]/g, '').replace(/\./g, '').replace(',', '.').trim();
      rawVal = parseFloat(cleaned) || 2400000;
    }
  }
  if (!rawVal || rawVal <= 0) rawVal = 2400000;

  const pos = cand.position || 'Deputado Federal';
  const state = cand.state || 'BR';
  const city = cand.city || state;
  const problems = cand.jurisdictionProblemsMatch?.problems || [];
  const prob1 = problems[0]?.title || `Filas no SUS (${state})`;
  const prob2 = problems[1]?.title || `Segurança Pública (${state})`;
  const prob3 = problems[2]?.title || `Infraestrutura e Gestão Fiscal (${state})`;

  const formattedValue = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format(rawVal);

  if (pos.includes('Presidente')) {
    const casas = Math.floor(rawVal / 130000);
    const ambulancias = Math.floor(rawVal / 250000);
    const etes = (rawVal / 25000000).toFixed(1);
    return {
      totalSpent: formattedValue,
      scopeTitle: 'Poder Executivo Federal (Presidência da República)',
      constitutionalDuty: 'Direção superior da administração federal, políticas nacionais de habitação, infraestrutura de saneamento e saúde pública (Art. 6º, 23 e 84 da CF/88).',
      shortSummary: `${casas.toLocaleString('pt-BR')} casas populares ou ${ambulancias.toLocaleString('pt-BR')} ambulâncias do SAMU`,
      items: [
        {
          title: `${casas.toLocaleString('pt-BR')} Casas Populares Construídas`,
          desc: 'Unidades habitacionais completas de interesse social para famílias de baixa renda sem teto.',
          target: 'Enfrentamento do déficit habitacional nacional e áreas de risco.'
        },
        {
          title: `${ambulancias.toLocaleString('pt-BR')} Ambulâncias de Resgate para o SAMU`,
          desc: 'Renovação e expansão da frota do SAMU para atendimento emergencial de urgência em todo o país.',
          target: prob1
        },
        {
          title: `${etes} Estações de Tratamento de Esgoto e Saneamento`,
          desc: 'Infraestrutura completa de saneamento básico beneficiando diretamente centenas de milhares de cidadãos.',
          target: 'Universalização do saneamento e combate à mortalidade infantil.'
        }
      ],
      verdict: `Com o investimento de ${formattedValue} declarado nesta campanha eleitoral, a União poderia ter entregue ${casas.toLocaleString('pt-BR')} residências populares completas para famílias sem teto ou adquirido ${ambulancias.toLocaleString('pt-BR')} ambulâncias novas para salvar vidas na rede do SUS.`
    };
  }

  if (pos.includes('Governador')) {
    const leitos = Math.floor(rawVal / 450000);
    const viaturas = Math.floor(rawVal / 220000);
    const escolas = Math.floor(rawVal / 300000);
    return {
      totalSpent: formattedValue,
      scopeTitle: `Poder Executivo Estadual (Governo de ${state})`,
      constitutionalDuty: `Comando das forças de segurança pública (PM e PC), gestão da rede de hospitais estaduais de alta complexidade e escolas de ensino médio (Art. 28, 144 e 198 da CF/88).`,
      shortSummary: `${leitos.toLocaleString('pt-BR')} leitos de UTI equipados ou ${viaturas.toLocaleString('pt-BR')} viaturas policiais`,
      items: [
        {
          title: `${leitos.toLocaleString('pt-BR')} Novos Leitos de UTI Equipados no SUS`,
          desc: `Leitos de tratamento intensivo completos na rede hospitalar estadual para zerar filas de casos graves em ${state}.`,
          target: prob1
        },
        {
          title: `${viaturas.toLocaleString('pt-BR')} Viaturas Policiais Blindadas com Câmeras IA`,
          desc: `Veículos táticos operacionais modernos para patrulhamento ostensivo e combate a facções em ${state}.`,
          target: prob2
        },
        {
          title: `${escolas.toLocaleString('pt-BR')} Escolas Estaduais de Ensino Médio Reformadas`,
          desc: `Climatização integral de salas, laboratórios de informática e conectividade para jovens estudantes.`,
          target: 'Infraestrutura educacional e redução da evasão escolar de jovens.'
        }
      ],
      verdict: `O custo de ${formattedValue} aplicado na campanha ao Governo de ${state} seria suficiente para equipar ${leitos.toLocaleString('pt-BR')} leitos de UTI na rede pública hospitalar ou colocar ${viaturas.toLocaleString('pt-BR')} novas viaturas blindadas para proteger os cidadãos nas ruas.`
    };
  }

  if (pos.includes('Prefeito')) {
    const creches = Math.floor(rawVal / 3500000) || 1;
    const vagasCreche = creches * 200;
    const kmAsfalto = (rawVal / 800000).toFixed(1);
    const ubss = Math.floor(rawVal / 1200000) || 2;
    return {
      totalSpent: formattedValue,
      scopeTitle: `Poder Executivo Municipal (Prefeitura de ${city})`,
      constitutionalDuty: `Atenção primária à saúde (UBS), transporte coletivo, creches integrais, zeladoria urbana e saneamento local (Art. 30 da CF/88).`,
      shortSummary: `${creches} novas creches integrais (${vagasCreche.toLocaleString('pt-BR')} vagas) ou ${kmAsfalto} km de asfalto e drenagem`,
      items: [
        {
          title: `${creches} Creches Municipais em Tempo Integral`,
          desc: `Abertura de ${vagasCreche.toLocaleString('pt-BR')} vagas para acolher crianças de famílias vulneráveis e mães trabalhadoras de ${city}.`,
          target: 'Eliminação da fila de espera por vagas na educação infantil.'
        },
        {
          title: `${kmAsfalto} km de Pavimentação Asfáltica e Drenagem`,
          desc: `Obras viárias estruturantes para acabar com buracos e pontos crônicos de alagamento nos bairros periféricos.`,
          target: prob3
        },
        {
          title: `${ubss} Novas Unidades Básicas de Saúde (UBS)`,
          desc: `Postos municipais completos com equipes de Saúde da Família e consultórios odontológicos.`,
          target: prob1
        }
      ],
      verdict: `Com os ${formattedValue} gastos na disputa pela prefeitura de ${city}, o poder público poderia ter criado ${vagasCreche.toLocaleString('pt-BR')} vagas em creches de tempo integral ou pavimentado e drenado ${kmAsfalto} km de ruas que sofrem com enchentes.`
    };
  }

  // Padrão: Deputado Federal / Estadual / Senador (Poder Legislativo)
  const ambulancias = Math.floor(rawVal / 200000);
  const consultas = Math.floor(rawVal / 65);
  const reformasPostos = Math.floor(rawVal / 150000);
  return {
    totalSpent: formattedValue,
    scopeTitle: `Poder Legislativo (${pos} por ${state})`,
    constitutionalDuty: `Prerrogativa orçamentária para destinação de emendas impositivas e fiscalização do erário para atender as prioridades de ${state} (Art. 166 da CF/88).`,
    shortSummary: `${ambulancias} ambulâncias para o SAMU ou ${consultas.toLocaleString('pt-BR')} consultas e exames no SUS`,
    items: [
      {
        title: `${ambulancias} Ambulâncias de Resgate para o SAMU`,
        desc: `Veículos equipados de socorro emergencial para atendimento rápido a pacientes em municípios de ${state}.`,
        target: prob1
      },
      {
        title: `${consultas.toLocaleString('pt-BR')} Consultas e Exames no SUS`,
        desc: `Consultas especializadas (oftalmologia, cardiologia) e diagnósticos de imagem para zerar a fila de regulação.`,
        target: prob1
      },
      {
        title: `${reformasPostos} Postos de Saúde (UBS) Reformados`,
        desc: `Modernização física, pintura, acessibilidade e novos equipamentos para unidades básicas de saúde de ${state}.`,
        target: prob3
      }
    ],
    verdict: `O total de ${formattedValue} gasto nesta campanha parlamentar poderia ter financiado ${ambulancias} ambulâncias de urgência para o SAMU ou viabilizado ${consultas.toLocaleString('pt-BR')} consultas e exames especializados para cidadãos que esperam na fila do SUS.`
  };
}

function detectConflictOfInterest(cand) {
  if (!cand || cand.officePower === 'judiciario') {
    return { hasConflictRisk: false, severity: 'BAIXO', status: 'NAO_APLICAVEL', alertMessage: '🛡️ Magistrado: Sem financiamento eleitoral (vedação constitucional).' };
  }
  const sectorFunding = cand.sectorFunding || [
    { sector: 'Doações de Pessoas Físicas / Financiamento Coletivo', percentage: 14.5 },
    { sector: 'Comércio & Serviços Locais', percentage: 8.2 }
  ];
  const nominalVotes = cand.nominalVotes || [];
  const heavySectors = sectorFunding.filter(s => Number(s.percentage || 0) > 20.0);

  if (heavySectors.length === 0) {
    return {
      hasConflictRisk: false,
      severity: 'BAIXO',
      status: 'ISENTO_DE_CONFLITO',
      alertMessage: '🛡️ Sem Conflito Detectado: Financiamento difuso (< 20% de concentração setorial).',
      maxSectorConcentration: Math.max(...sectorFunding.map(s => Number(s.percentage || 0)))
    };
  }

  for (const sectorItem of heavySectors) {
    const matchingVotes = nominalVotes.filter(v =>
      v.sector && v.sector.toLowerCase().includes(sectorItem.sector.toLowerCase().split(' ')[0])
    );
    for (const vote of matchingVotes) {
      const votedProSector = (vote.vote === 'SIM' && vote.proSectorBeneficial === true) ||
                             (vote.vote === 'NÃO' && vote.proSectorBeneficial === false);
      if (votedProSector) {
        return {
          hasConflictRisk: true,
          severity: 'ALTO',
          status: 'CONFLITO_POTENCIAL',
          conflictSector: sectorItem.sector,
          financingPercentage: Number(sectorItem.percentage),
          financingAmount: sectorItem.amount || 'R$ 500.000,00',
          billId: vote.billId || 'Proposição Nominal',
          billTitle: vote.billTitle || 'Matéria Legislativa Setorial',
          parliamentaryVote: vote.vote,
          alertMessage: `⚠️ Alerta de Conflito de Interesses: Parlamentar votou favoravelmente a proposição do setor de ${sectorItem.sector}, responsável por ${sectorItem.percentage}% de sua arrecadação de campanha (> 20% threshold).`,
          recommendation: 'Recomenda-se transparência declaratória prévia perante o Conselho de Ética.'
        };
      }
    }
  }

  return {
    hasConflictRisk: false,
    severity: 'BAIXO',
    status: 'ISENTO_DE_CONFLITO_EM_VOTACOES',
    alertMessage: '🛡️ Isento de Conflito em Votações: Embora possua setor com financiamento expressivo, o parlamentar não registrou votações favoráveis divergentes do interesse público.'
  };
}

function calculatePredictiveMigration(cand) {
  if (!cand || cand.officePower === 'judiciario') {
    return {
      reelectionProbabilityPct: 0,
      partyMigrationRisk: 'Isento',
      partyMigrationProbabilityPct: 0,
      governmentCoalitionAlignmentPct: 0,
      analyticalVerdict: 'Cargo vitalício não submetido a eleições nem a janelas partidárias (Art. 95 da CF/88).'
    };
  }

  const discipline = typeof cand.partyDisciplinePct === 'number' ? cand.partyDisciplinePct : 85;
  const govAlignment = typeof cand.governmentAlignmentPct === 'number' ? cand.governmentAlignmentPct : 50;
  const switches = typeof cand.pastPartySwitchesCount === 'number' ? cand.pastPartySwitchesCount : 1;
  const score = typeof cand.overallScore === 'number' ? cand.overallScore : 70;
  const attendance = typeof cand.attendanceRatePct === 'number' 
    ? cand.attendanceRatePct 
    : (cand.attendance?.ratePct || 90);
  const party = cand.party || 'Legenda';

  const zReelect = -4.5 + (0.04 * score) + (0.03 * attendance) + (0.015 * discipline) - (0.3 * switches);
  const rawReelectProb = (1 / (1 + Math.exp(-zReelect))) * 100;
  const reelectionProbabilityPct = Math.round(Math.min(95, Math.max(10, rawReelectProb)) * 10) / 10;

  let migrationProb = 0;
  if (discipline < 70) {
    migrationProb = 60 + ((70 - discipline) * 1.2) + (switches * 5);
  } else if (discipline < 85) {
    migrationProb = 25 + ((85 - discipline) * 1.5) + (switches * 4);
  } else {
    migrationProb = Math.max(5, 15 - ((discipline - 85) * 0.5) + (switches * 2));
  }
  const partyMigrationProbabilityPct = Math.round(Math.min(92, Math.max(5, migrationProb)) * 10) / 10;

  let partyMigrationRisk = 'Baixo';
  if (partyMigrationProbabilityPct >= 55) {
    partyMigrationRisk = 'Alto';
  } else if (partyMigrationProbabilityPct >= 25) {
    partyMigrationRisk = 'Moderado';
  }

  let analyticalVerdict = '';
  if (partyMigrationRisk === 'Alto') {
    analyticalVerdict = `⚠️ Risco Elevado de Migração na Janela Partidária (${partyMigrationProbabilityPct}%): Baixa fidelidade partidária (${discipline}%) e histórico de trocas de legenda indicam forte chance de migração antes de 2026.`;
  } else if (partyMigrationRisk === 'Moderado') {
    analyticalVerdict = `⚖️ Estabilidade Partidária Moderada (${partyMigrationProbabilityPct}%): Fidelidade de ${discipline}%. Projeção de reeleição estimada em ${reelectionProbabilityPct}%.`;
  } else {
    analyticalVerdict = `🛡️ Alta coesão partidária (${discipline}% de fidelidade à bancada do ${party}). Projeção de reeleição robusta em ${reelectionProbabilityPct}%. Risco de migração na janela: Baixo (${partyMigrationProbabilityPct}%).`;
  }

  return {
    reelectionProbabilityPct,
    partyMigrationRisk,
    partyMigrationProbabilityPct,
    governmentCoalitionAlignmentPct: govAlignment,
    stabilityIndex: Math.round((100 - partyMigrationProbabilityPct) * 10) / 10,
    analyticalVerdict
  };
}

function generateMetricAuditHash(cand) {
  if (!cand) return { radarHash: 'sha256:00000000', overallScore: 0 };
  const attendance = cand.attendance || {};
  const salary = cand.salary || {};
  const amendments = cand.parliamentaryAmendments || {};
  const debate = cand.recentDebate || {};
  const processes = cand.legalProcesses || {};

  const manifest = {
    candidateId: String(cand.id || ''),
    ballotName: String(cand.ballotName || cand.name || ''),
    position: String(cand.position || ''),
    state: String(cand.state || 'BR'),
    attendance: {
      presentCount: Number(attendance.presentCount || 0),
      totalSessions: Number(attendance.totalSessions || 0),
      unjustifiedAbsences: Number(attendance.unjustifiedAbsences || 0),
      ratePct: Number(attendance.ratePct || 0)
    },
    ceapFiscal: {
      spendingMonthly: Number(salary.spendingCeapMonthlyNum || 0),
      limitMonthly: Number(salary.limitCeapMonthlyNum || 45000),
      spendingPct: Number(salary.spendingPercentage || 0)
    },
    parliamentaryAmendments: {
      totalAllocated: String(amendments.totalAllocated || 'R$ 0,00'),
      executionRatePct: Number(amendments.executionRatePct || 0),
      directPixPct: Number(amendments.directPixPct || 0)
    },
    factChecking: {
      truthfulnessPct: Number(debate.truthfulnessPct || 80),
      rightOfReplyGranted: Number(debate.rightOfReplyGranted || 0)
    },
    legalIntegrity: {
      processCount: Number(processes.count || 0),
      cleanSlateStatus: String(cand.fichaLimpaStatus || 'FICHA_LIMPA')
    },
    calculatedScore: Number(cand.overallScore || 0)
  };

  const canonicalJson = JSON.stringify(manifest);
  let hashHex = '';
  if (typeof require !== 'undefined') {
    try {
      const crypto = require('node:crypto');
      hashHex = crypto.createHash('sha256').update(canonicalJson, 'utf8').digest('hex');
    } catch {}
  }
  if (!hashHex) {
    let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
    for (let i = 0; i < canonicalJson.length; i++) {
      const ch = canonicalJson.charCodeAt(i);
      h1 = Math.imul(h1 ^ ch, 2654435761);
      h2 = Math.imul(h2 ^ ch, 1597334677);
    }
    h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507);
    h1 ^= Math.imul(h2 ^ (h2 >>> 13), 3266489909);
    h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507);
    h2 ^= Math.imul(h1 ^ (h1 >>> 13), 3266489909);
    hashHex = (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16).padStart(16, '0') +
              (4294967296 * (2097151 & h1) + (h2 >>> 0)).toString(16).padStart(16, '0');
  }

  const radarHash = `sha256:${hashHex}`;
  return {
    radarHash,
    overallScore: manifest.calculatedScore,
    algorithmVersion: 'CivicScore-v2.6-Deterministic',
    slaContraditorioDays: 5,
    reproducibleUrl: `/api/audit/${manifest.candidateId}`,
    rawInputsManifest: manifest,
    legalNotice: 'Cálculo auditável e reproduzível com base em fontes oficiais (TSE DivulgaCand, Câmara dos Deputados e CNJ). Contraditório oficial assegurado.'
  };
}

if (typeof window !== 'undefined') {
  window.candidatesData = candidatesData;
  window.incumbentsData = incumbentsData;
  window.getSafeAvatarUrl = getSafeAvatarUrl;
  window.getSafeAvatarFallback = getSafeAvatarFallback;
  window.calculateCivicRelativization = calculateCivicRelativization;
  window.detectConflictOfInterest = detectConflictOfInterest;
  window.calculatePredictiveMigration = calculatePredictiveMigration;
  window.generateMetricAuditHash = generateMetricAuditHash;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { 
    candidatesData, 
    incumbentsData, 
    getSafeAvatarUrl, 
    getSafeAvatarFallback,
    calculateCivicRelativization,
    detectConflictOfInterest,
    calculatePredictiveMigration,
    generateMetricAuditHash
  };
}

